  it("fails fast when stdin is open but no input ever arrives", async () => {
    const child = spawn(process.execPath, [CLI_PATH, "batch"], {
      cwd: tempDir,
      stdio: ["pipe", "pipe", "pipe"],
      env: { ...process.env, KSPEC_AUTHOR: "@test" },
    });

    let stderr = "";
