    expect(taskData.priority).toBe(2);
    expect(taskData.tags).toContain("batch-test");
  });
});

// ── KSPEC_SPEC_DIR Override ──────────────────────────────────────────

describe("KSPEC_SPEC_DIR environment variable", () => {
